module bus_time_calculator (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [31:0] n,\n    input wire [31:0] l,\n    input wire [31:0] v1,\n    input wire [31:0] v2,\n    input wire [31:0] k,\n    output reg [31:0] time,\n    output reg done\n);\n\nreg [2:0] state;\nreg [7:0] iter;\nreg [31:0] m, L, R, M, S, T;\n\nfunction [31:0] q_mul;\n    input [31:0] a, b;\n    begin\n        q_mul = (a * b) >> 16;\n    end\nendfunction\n\nlocalparam [2:0] IDLE  = 3'd0;\nlocalparam [2:0] INIT  = 3'd1;\nlocalparam [2:0] LOOP  = 3'd2;\nlocalparam [2:0] CALC  = 3'd3;\nlocalparam [2:0] UPDATE = 3'd4;\nlocalparam [2:0] DONE  = 3'd5;\n\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= IDLE;\n        done <= 1'b0;\n        time <= 32'd0;\n        iter <= 8'd0;\n        m <= 32'd0;\n        L <= 32'd0;\n        R <= 32'd0;\n        M <= 32'd0;\n        S <= 32'd0;\n        T <= 32'd0;\n    end else begin\n        case (state)\n            IDLE: begin\n                done <= 1'b0;\n                if (start) state <= INIT;\n            end\n            INIT: begin\n                m <= (n + k - 32'd1) / k;\n                L <= 32'd0;\n                R <= l;\n                iter <= 8'd0;\n                state <= LOOP;\n            end\n            LOOP: begin\n                if (iter >= 8'd16) begin\n                    time <= M;\n                    state <= DONE;\n                end else begin\n                    M <= (L + R) >> 1;\n                    state <= CALC;\n                end\n            end\n            CALC: begin\n                S <= l - M;\n                T <= q_mul(M, (m << 1) - 32'd1) - l;\n                state <= UPDATE;\n            end\n            UPDATE: begin\n                if (q_mul(T, v1) > q_mul(S, v2)) begin\n                    R <= M;\n                end else begin\n                    L <= M;\n                end\n                iter <= iter + 8'd1;\n                state <= LOOP;\n            end\n            DONE: begin\n                done <= 1'b1;\n                state <= IDLE;\n            end\n            default: state <= IDLE;\n        endcase\n    end\nend\n\nendmodule